<?php

declare(strict_types=1);

require_once dirname(__DIR__) . '/src/bootstrap.php';

use AAB\LeaseFlow\PdfService;

$uri = trim((string) parse_url($_SERVER['REQUEST_URI'] ?? '/', PHP_URL_PATH), '/');
$method = $_SERVER['REQUEST_METHOD'] ?? 'GET';

function render_head(string $title, ?array $user = null): void {
    echo '<!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.e($title).' · AAB LeaseFlow</title><link rel="stylesheet" href="'.e(base_url('assets/app.css')).'"></head><body>';
    if ($user) {
        echo '<header class="topbar"><a class="brand" href="'.e(base_url('dashboard')).'">AAB <span>LeaseFlow</span></a><nav class="nav"><a href="'.e(base_url('cases')).'">Dossiers</a>';
        if (in_array($user['role'], ['processor','manager','admin'], true)) echo '<a href="'.e(base_url('processing')).'">Verwerking</a>';
        echo '<a href="'.e(base_url('logout')).'">'.e($user['name']).' · Uitloggen</a></nav></header>';
    }
}
function render_foot(): void { echo '</body></html>'; }
function flashes(): void { foreach (pull_flashes() as $f) echo '<div class="flash '.e($f['type']).'">'.e($f['message']).'</div>'; }
function get_case(int $id): array {
    $s=db()->prepare('SELECT c.*,cu.first_name,cu.last_name,cu.email customer_email,cu.phone customer_phone,p.name partner_name,u.name seller_name,pr.name processor_name FROM lease_cases c JOIN customers cu ON cu.id=c.customer_id JOIN lease_partners p ON p.id=c.lease_partner_id JOIN users u ON u.id=c.seller_id LEFT JOIN users pr ON pr.id=c.processor_id WHERE c.id=?');$s->execute([$id]);$row=$s->fetch();if(!$row){http_response_code(404);exit('Dossier niet gevonden.');}return $row;
}
function can_view_case(array $user,array $case): bool { return in_array($user['role'],['processor','manager','admin'],true)||(int)$case['seller_id']===(int)$user['id']; }

if ($uri === 'login') {
    if ($method === 'POST') {
        verify_csrf(); $email=trim((string)($_POST['email']??'')); $pw=(string)($_POST['password']??'');
        $s=db()->prepare('SELECT * FROM users WHERE email=? AND active=1');$s->execute([$email]);$u=$s->fetch();
        if($u && password_verify($pw,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];redirect('dashboard');}
        flash('error','Onjuiste login.');redirect('login');
    }
    render_head('Inloggen'); echo '<main class="login"><div class="card"><div class="brand" style="color:#111827;font-size:22px;margin-bottom:22px">AAB <span>LeaseFlow</span></div>';flashes();echo '<form method="post"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><div class="field"><label>E-mail</label><input type="email" name="email" required autofocus></div><div class="field"><label>Wachtwoord</label><input type="password" name="password" required></div><button class="btn green" style="width:100%">Inloggen</button></form></div></main>';render_foot();exit;
}
if ($uri === 'logout') { session_destroy(); redirect('login'); }

if (preg_match('#^sign/([^/]+)$#',$uri,$m)) {
    $token=$m[1];$hash=hash('sha256',$token);
    $s=db()->prepare('SELECT sr.*,d.id document_id,d.title,d.current_version,c.case_number,c.id case_id,c.status case_status,cu.first_name,cu.last_name,p.name partner_name,c.bike_brand,c.bike_model,dv.storage_path,dv.sha256_hash original_hash FROM signature_requests sr JOIN documents d ON d.id=sr.document_id JOIN lease_cases c ON c.id=sr.lease_case_id JOIN customers cu ON cu.id=c.customer_id JOIN lease_partners p ON p.id=c.lease_partner_id JOIN document_versions dv ON dv.document_id=d.id AND dv.version=d.current_version WHERE sr.token_hash=? LIMIT 1');$s->execute([$hash]);$req=$s->fetch();
    if(!$req||in_array($req['status'],['revoked','signed'],true)||strtotime($req['expires_at'])<time()){http_response_code(410);render_head('Tekenlink niet geldig');echo '<main class="sign-wrap"><div class="card"><h1>Deze tekenlink is niet meer geldig</h1><p class="muted">Neem contact op met Aerts Action Bike voor een nieuwe link.</p></div></main>';render_foot();exit;}
    if(!$req['opened_at']){db()->prepare("UPDATE signature_requests SET status='opened',opened_at=NOW(),ip_address=?,user_agent=? WHERE id=?")->execute([client_ip(),user_agent(),$req['id']]);audit((int)$req['case_id'],'SIGN_REQUEST_OPENED',[],'customer');}
    if($method==='POST'){
        verify_csrf();
        if(empty($_POST['accepted'])){flash('error','Bevestig dat u het document heeft gelezen.');redirect('sign/'.$token);}
        $data=(string)($_POST['signature']??'');if(!preg_match('#^data:image/png;base64,(.+)$#',$data,$mm)){flash('error','Plaats eerst uw handtekening.');redirect('sign/'.$token);}
        $binary=base64_decode($mm[1],true);if($binary===false||strlen($binary)<100){flash('error','Handtekening is ongeldig.');redirect('sign/'.$token);}
        $dir=case_storage_dir($req['case_number']);$sigPath=$dir.'/signature-'.$req['id'].'.png';file_put_contents($sigPath,$binary);
        $src=dirname(__DIR__).'/'.$req['storage_path'];$newVersion=(int)$req['current_version']+1;$dest=$dir.'/signed-v'.$newVersion.'.pdf';
        PdfService::applySignature($src,$sigPath,$dest,(int)$req['page_number'],(float)$req['position_x'],(float)$req['position_y'],(float)$req['width_ratio'],(float)$req['height_ratio'],$req['signer_name'],date('d/m/Y H:i'));
        $after=hash_file('sha256',$dest);$rel=ltrim(str_replace(dirname(__DIR__),'',$dest),'/\\');
        db()->beginTransaction();
        try{
            $ins=db()->prepare('INSERT INTO document_versions(document_id,version,storage_path,original_name,mime_type,file_size,sha256_hash,uploaded_by) VALUES(?,?,?,?,?,?,?,NULL)');$ins->execute([$req['document_id'],$newVersion,$rel,$req['case_number'].'-signed.pdf','application/pdf',filesize($dest),$after]);$versionId=(int)db()->lastInsertId();
            db()->prepare("UPDATE documents SET current_version=?,status='locked' WHERE id=?")->execute([$newVersion,$req['document_id']]);
            db()->prepare("UPDATE signature_requests SET status='signed',accepted_at=NOW(),signed_at=NOW(),ip_address=?,user_agent=? WHERE id=?")->execute([client_ip(),user_agent(),$req['id']]);
            db()->prepare('INSERT INTO signatures(signature_request_id,signature_path,document_hash_before,document_hash_after,signed_document_version_id,signed_at,ip_address) VALUES(?,?,?,?,?,NOW(),?)')->execute([$req['id'],ltrim(str_replace(dirname(__DIR__),'',$sigPath),'/\\'),$req['original_hash'],$after,$versionId,client_ip()]);
            db()->prepare("UPDATE lease_cases SET status='ready_for_processing',signed_at=NOW() WHERE id=?")->execute([$req['case_id']]);
            db()->prepare('INSERT INTO status_history(lease_case_id,from_status,to_status,reason) VALUES(?,?,?,?)')->execute([$req['case_id'],$req['case_status'],'ready_for_processing','Document ondertekend door klant']);
            audit((int)$req['case_id'],'DOCUMENT_SIGNED',['document_id'=>$req['document_id'],'sha256'=>$after],'customer');db()->commit();
        }catch(Throwable $e){db()->rollBack();throw $e;}
        render_head('Ondertekend');echo '<main class="sign-wrap"><div class="card" style="text-align:center"><h1>✓ Document ondertekend</h1><p>Bedankt, '.e($req['signer_name']).'. De getekende bestelbon is automatisch doorgestuurd voor verwerking.</p><p class="muted">Dossier '.e($req['case_number']).'</p></div></main>';render_foot();exit;
    }
    render_head('Bestelbon ondertekenen');echo '<main class="sign-wrap">';flashes();echo '<div class="card"><h1>Bestelbon fietsleasing</h1><p><b>'.e($req['signer_name']).'</b> · '.e($req['partner_name']).' · '.e($req['bike_brand'].' '.$req['bike_model']).'</p><iframe class="pdf-frame" src="'.e(base_url('document-public/'.$token)).'"></iframe></div><div class="card" style="margin-top:18px"><h2>Handtekening</h2><form method="post" id="signForm"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="signature" id="signatureData"><canvas class="signature" id="signature"></canvas><div class="actions" style="margin-top:10px"><button type="button" class="btn soft" id="clear">Wissen</button></div><label style="margin-top:18px;font-weight:500"><input style="width:auto" type="checkbox" name="accepted" value="1" required> Ik bevestig dat ik het document heb gelezen en wil ondertekenen.</label><button class="btn green" style="margin-top:16px">Definitief ondertekenen</button></form></div></main><script src="https://cdn.jsdelivr.net/npm/signature_pad@5.0.4/dist/signature_pad.umd.min.js"></script><script>const c=document.getElementById("signature"),p=new SignaturePad(c,{minWidth:1,maxWidth:2.5});function r(){const d=Math.max(window.devicePixelRatio||1,1);c.width=c.offsetWidth*d;c.height=210*d;c.getContext("2d").scale(d,d);p.clear()}window.addEventListener("resize",r);r();document.getElementById("clear").onclick=()=>p.clear();document.getElementById("signForm").onsubmit=e=>{if(p.isEmpty()){e.preventDefault();alert("Plaats eerst uw handtekening.");return}document.getElementById("signatureData").value=p.toDataURL("image/png")}</script>';render_foot();exit;
}

if (preg_match('#^document-public/([^/]+)$#',$uri,$m)) {
    $h=hash('sha256',$m[1]);$s=db()->prepare('SELECT dv.storage_path FROM signature_requests sr JOIN documents d ON d.id=sr.document_id JOIN document_versions dv ON dv.document_id=d.id AND dv.version=d.current_version WHERE sr.token_hash=? AND sr.status IN (\'pending\',\'opened\') AND sr.expires_at>NOW()');$s->execute([$h]);$path=$s->fetchColumn();if(!$path){http_response_code(404);exit;}header('Content-Type: application/pdf');header('Content-Disposition: inline');readfile(dirname(__DIR__).'/'.$path);exit;
}

$user=require_auth();

if ($uri===''||$uri==='dashboard') {
    $where=$user['role']==='seller'?' WHERE seller_id='.(int)$user['id']:'';
    $counts=[];foreach(['waiting_for_customer','ready_for_processing','missing_info','processed'] as $st){$q=db()->query("SELECT COUNT(*) FROM lease_cases{$where}".($where?' AND ':' WHERE ')."status=".db()->quote($st));$counts[$st]=(int)$q->fetchColumn();}
    $sql='SELECT c.id,c.case_number,c.status,c.updated_at,cu.first_name,cu.last_name,p.name partner_name,c.bike_brand,c.bike_model FROM lease_cases c JOIN customers cu ON cu.id=c.customer_id JOIN lease_partners p ON p.id=c.lease_partner_id'.($user['role']==='seller'?' WHERE c.seller_id=?':'').' ORDER BY c.updated_at DESC LIMIT 12';$s=db()->prepare($sql);$s->execute($user['role']==='seller'?[$user['id']]:[]);$cases=$s->fetchAll();
    render_head('Dashboard',$user);echo '<main class="shell">';flashes();echo '<div class="case-head"><div><h1>Leasingdashboard</h1><p class="muted">Van bestelbon tot verwerking in één dossier.</p></div><a class="btn green" href="'.e(base_url('cases/create')).'">+ Nieuw leasingdossier</a></div><div class="grid grid-4" style="margin:22px 0"><div class="card metric"><span>Wacht op klant</span><b>'.$counts['waiting_for_customer'].'</b></div><div class="card metric"><span>Klaar voor verwerking</span><b>'.$counts['ready_for_processing'].'</b></div><div class="card metric"><span>Actie vereist</span><b>'.$counts['missing_info'].'</b></div><div class="card metric"><span>Verwerkt</span><b>'.$counts['processed'].'</b></div></div><div class="card"><h2>Recente dossiers</h2>';case_table($cases);echo '</div></main>';render_foot();exit;
}

if ($uri==='cases') {
    $sql='SELECT c.id,c.case_number,c.status,c.updated_at,cu.first_name,cu.last_name,p.name partner_name,c.bike_brand,c.bike_model FROM lease_cases c JOIN customers cu ON cu.id=c.customer_id JOIN lease_partners p ON p.id=c.lease_partner_id'.($user['role']==='seller'?' WHERE c.seller_id=?':'').' ORDER BY c.updated_at DESC';$s=db()->prepare($sql);$s->execute($user['role']==='seller'?[$user['id']]:[]);render_head('Dossiers',$user);echo '<main class="shell"><div class="case-head"><div><h1>Dossiers</h1></div><a class="btn green" href="'.e(base_url('cases/create')).'">+ Nieuw dossier</a></div><div class="card" style="margin-top:20px">';case_table($s->fetchAll());echo '</div></main>';render_foot();exit;
}

if ($uri==='cases/create') {
    if($method==='POST'){
        verify_csrf();
        db()->beginTransaction();try{
            $s=db()->prepare('INSERT INTO customers(first_name,last_name,email,phone,customer_number) VALUES(?,?,?,?,?)');$s->execute([trim($_POST['first_name']),trim($_POST['last_name']),trim($_POST['email']),trim($_POST['phone']??''),trim($_POST['customer_number']??'')]);$cid=(int)db()->lastInsertId();
            $s=db()->prepare('INSERT INTO lease_cases(case_number,customer_id,lease_partner_id,seller_id,status,external_reference,employer,lease_duration,bike_brand,bike_model,bike_sku,bike_size,bike_color,serial_number,total_amount,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute(['TEMP-'.$cid,$cid,(int)$_POST['lease_partner_id'],$user['id'],'concept',trim($_POST['external_reference']??''),trim($_POST['employer']??''),(int)($_POST['lease_duration']??0)?:null,trim($_POST['bike_brand']),trim($_POST['bike_model']),trim($_POST['bike_sku']??''),trim($_POST['bike_size']??''),trim($_POST['bike_color']??''),trim($_POST['serial_number']??''),($_POST['total_amount']??'')!==''?(float)$_POST['total_amount']:null,trim($_POST['notes']??'')]);$id=(int)db()->lastInsertId();$num=case_number($id);db()->prepare('UPDATE lease_cases SET case_number=? WHERE id=?')->execute([$num,$id]);db()->prepare('INSERT INTO status_history(lease_case_id,to_status,changed_by,reason) VALUES(?,?,?,?)')->execute([$id,'concept',$user['id'],'Dossier aangemaakt']);audit($id,'CASE_CREATED',['case_number'=>$num]);db()->commit();flash('success','Dossier '.$num.' aangemaakt.');redirect('cases/'.$id);
        }catch(Throwable $e){db()->rollBack();throw $e;}
    }
    $partners=db()->query('SELECT * FROM lease_partners WHERE active=1 ORDER BY name')->fetchAll();render_head('Nieuw dossier',$user);echo '<main class="shell"><h1>Nieuw leasingdossier</h1><form method="post"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><div class="grid grid-2" style="margin-top:20px"><div class="card"><h2>Klant</h2>'.field('Voornaam *','first_name','',true).field('Achternaam *','last_name','',true).field('E-mail *','email','',true,'email').field('Telefoon','phone').field('Tilroy klantnummer','customer_number').'</div><div class="card"><h2>Leasing</h2><div class="field"><label>Leasepartner *</label><select name="lease_partner_id" required><option value="">Kies...</option>';foreach($partners as $p)echo '<option value="'.$p['id'].'">'.e($p['name']).'</option>';echo '</select></div>'.field('Lease referentie','external_reference').field('Werkgever','employer').field('Looptijd (maanden)','lease_duration','','false','number').'</div><div class="card"><h2>Fiets</h2>'.field('Merk *','bike_brand','',true).field('Model *','bike_model','',true).field('Artikelnummer','bike_sku').field('Maat','bike_size').field('Kleur','bike_color').field('Serienummer','serial_number').field('Totaalbedrag','total_amount','','false','number','0.01').'</div><div class="card"><h2>Interne notitie</h2><textarea name="notes" rows="8" placeholder="Optionele interne context"></textarea></div></div><button class="btn green" style="margin-top:18px">Dossier aanmaken</button></form></main>';render_foot();exit;
}

if (preg_match('#^cases/(\d+)$#',$uri,$m)) {
    $case=get_case((int)$m[1]);if(!can_view_case($user,$case)){http_response_code(403);exit('Geen toegang.');}
    $s=db()->prepare('SELECT d.*,dv.id version_id,dv.storage_path,dv.original_name,dv.sha256_hash,dv.created_at version_created FROM documents d JOIN document_versions dv ON dv.document_id=d.id AND dv.version=d.current_version WHERE d.lease_case_id=? ORDER BY d.id');$s->execute([$case['id']]);$docs=$s->fetchAll();$h=db()->prepare('SELECT sh.*,u.name user_name FROM status_history sh LEFT JOIN users u ON u.id=sh.changed_by WHERE lease_case_id=? ORDER BY sh.id DESC');$h->execute([$case['id']]);
    render_head($case['case_number'],$user);echo '<main class="shell">';flashes();echo '<div class="case-head"><div><h1>'.e($case['case_number']).'</h1><p>'.e($case['first_name'].' '.$case['last_name']).' · '.e($case['partner_name']).'</p></div><span class="badge '.e($case['status']).'">'.e(status_label($case['status'])).'</span></div><div class="grid grid-2" style="margin-top:20px"><div><div class="card"><h2>Fiets & leasing</h2><p><b>'.e($case['bike_brand'].' '.$case['bike_model']).'</b><br>'.e($case['bike_size']).' '.e($case['bike_color']).'</p><p>Leasepartner: <b>'.e($case['partner_name']).'</b><br>Referentie: '.e($case['external_reference']?:'—').'<br>Bedrag: '.($case['total_amount']?'€ '.number_format((float)$case['total_amount'],2,',','.'):'—').'</p></div><div class="card" style="margin-top:18px"><h2>Documenten</h2>';if(!$docs)echo '<p class="muted">Nog geen documenten.</p>';foreach($docs as $d)echo '<div style="padding:10px 0;border-bottom:1px solid #eee"><b>'.e($d['title']).'</b><br><span class="muted">v'.(int)$d['current_version'].' · SHA256 '.e(substr($d['sha256_hash'],0,12)).'…</span><div class="actions" style="margin-top:8px"><a class="btn soft" href="'.e(base_url('documents/'.$d['id'].'/view')).'" target="_blank">Bekijken</a></div></div>';if(!in_array($case['status'],['ready_for_processing','in_processing','processed','completed'],true))echo '<form method="post" enctype="multipart/form-data" action="'.e(base_url('cases/'.$case['id'].'/upload')).'" style="margin-top:16px"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><div class="field"><label>Bestelbon PDF</label><input type="file" name="pdf" accept="application/pdf" required></div><button class="btn">PDF uploaden</button></form>';echo '</div></div><div><div class="card"><h2>Volgende actie</h2>';if($case['status']==='document_uploaded')echo '<form method="post" action="'.e(base_url('cases/'.$case['id'].'/sign-request')).'"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><div class="field"><label>Pagina handtekening</label><input type="number" min="1" name="page_number" value="1"></div><p class="muted">De standaardpositie is rechtsonder. Dit wordt later visueel versleepbaar.</p><button class="btn green">Tekenlink genereren</button></form>';elseif($case['status']==='waiting_for_customer'){ $q=db()->prepare("SELECT id FROM signature_requests WHERE lease_case_id=? AND status IN ('pending','opened') ORDER BY id DESC LIMIT 1");$q->execute([$case['id']]);echo '<p>De klant kan de bestelbon nu ondertekenen. Om veiligheidsredenen wordt de bestaande token niet opnieuw getoond. Genereer een nieuwe link indien nodig.</p>'; }elseif($case['status']==='ready_for_processing')echo '<p>✓ Ondertekend en klaar voor verwerking.</p>';elseif($case['status']==='missing_info')echo '<p>De verwerker heeft aanvullende informatie gevraagd.</p>';else echo '<p class="muted">Upload de bestelbon om verder te gaan.</p>';echo '</div><div class="card" style="margin-top:18px"><h2>Historiek</h2><div class="timeline">';foreach($h->fetchAll() as $it)echo '<div class="timeline-item"><b>'.e(status_label($it['to_status'])).'</b><br><span class="muted">'.e($it['created_at']).' · '.e($it['user_name']?:'Systeem').'</span>'.($it['reason']?'<br>'.e($it['reason']):'').'</div>';echo '</div></div></div></div></main>';render_foot();exit;
}

if (preg_match('#^cases/(\d+)/upload$#',$uri,$m)&&$method==='POST') {
    $case=get_case((int)$m[1]);if(!can_view_case($user,$case)){http_response_code(403);exit;}verify_csrf();try{require_pdf_upload($_FILES['pdf']??[]);$dir=case_storage_dir($case['case_number']);$name='order-v'.date('YmdHis').'.pdf';$dest=$dir.'/'.$name;if(!move_uploaded_file($_FILES['pdf']['tmp_name'],$dest))throw new RuntimeException('Bestand kon niet worden opgeslagen.');$hash=hash_file('sha256',$dest);$rel=ltrim(str_replace(dirname(__DIR__),'',$dest),'/\\');db()->beginTransaction();$d=db()->prepare("INSERT INTO documents(lease_case_id,type,title,status,current_version) VALUES(?,'order_form','Bestelbon','uploaded',1)");$d->execute([$case['id']]);$did=(int)db()->lastInsertId();db()->prepare('INSERT INTO document_versions(document_id,version,storage_path,original_name,mime_type,file_size,sha256_hash,uploaded_by) VALUES(?,?,?,?,?,?,?,?)')->execute([$did,1,$rel,$_FILES['pdf']['name'],'application/pdf',filesize($dest),$hash,$user['id']]);change_status((int)$case['id'],'document_uploaded','Bestelbon geüpload',(int)$user['id']);audit((int)$case['id'],'PDF_UPLOADED',['document_id'=>$did,'sha256'=>$hash]);db()->commit();flash('success','Bestelbon veilig opgeslagen.');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();flash('error',$e->getMessage());}redirect('cases/'.$case['id']);
}

if (preg_match('#^cases/(\d+)/sign-request$#',$uri,$m)&&$method==='POST') {
    $case=get_case((int)$m[1]);if(!can_view_case($user,$case)){http_response_code(403);exit;}verify_csrf();$d=db()->prepare("SELECT id FROM documents WHERE lease_case_id=? AND type='order_form' ORDER BY id DESC LIMIT 1");$d->execute([$case['id']]);$did=$d->fetchColumn();if(!$did){flash('error','Upload eerst een bestelbon.');redirect('cases/'.$case['id']);}$token=signature_token();$hours=max(1,(int)envv('SIGN_LINK_HOURS',168));$exp=date('Y-m-d H:i:s',time()+$hours*3600);db()->prepare("UPDATE signature_requests SET status='revoked' WHERE lease_case_id=? AND status IN ('pending','opened')")->execute([$case['id']]);db()->prepare('INSERT INTO signature_requests(lease_case_id,document_id,token_hash,signer_name,signer_email,expires_at,page_number) VALUES(?,?,?,?,?,?,?)')->execute([$case['id'],$did,hash('sha256',$token),$case['first_name'].' '.$case['last_name'],$case['customer_email'],$exp,max(1,(int)($_POST['page_number']??1))]);change_status((int)$case['id'],'waiting_for_customer','Tekenverzoek aangemaakt',(int)$user['id']);audit((int)$case['id'],'SIGN_REQUEST_CREATED',['expires_at'=>$exp]);$_SESSION['_last_sign_link']=base_url('sign/'.$token);redirect('cases/'.$case['id'].'/sign-link');
}

if (preg_match('#^cases/(\d+)/sign-link$#',$uri,$m)) { $case=get_case((int)$m[1]);if(!can_view_case($user,$case)){http_response_code(403);exit;}$link=$_SESSION['_last_sign_link']??null;unset($_SESSION['_last_sign_link']);render_head('Tekenlink',$user);echo '<main class="shell"><div class="card"><h1>Tekenlink klaar</h1>';if($link)echo '<p>Deel deze beveiligde link met <b>'.e($case['first_name'].' '.$case['last_name']).'</b>:</p><input value="'.e($link).'" readonly onclick="this.select()"><div class="actions" style="margin-top:14px"><a class="btn green" href="'.e($link).'" target="_blank">Open tekenpagina</a><a class="btn soft" href="'.e(base_url('cases/'.$case['id'])).'">Terug naar dossier</a></div><p class="muted">De token wordt hierna niet opnieuw zichtbaar gemaakt.</p>';else echo '<p>De link werd om veiligheidsredenen niet opnieuw getoond. Genereer vanuit het dossier een nieuwe tekenlink.</p>';echo '</div></main>';render_foot();exit; }

if (preg_match('#^documents/(\d+)/view$#',$uri,$m)) { $s=db()->prepare('SELECT dv.storage_path,d.lease_case_id FROM documents d JOIN document_versions dv ON dv.document_id=d.id AND dv.version=d.current_version WHERE d.id=?');$s->execute([(int)$m[1]]);$d=$s->fetch();if(!$d){http_response_code(404);exit;}$case=get_case((int)$d['lease_case_id']);if(!can_view_case($user,$case)){http_response_code(403);exit;}audit((int)$case['id'],'PDF_VIEWED',['document_id'=>(int)$m[1]]);header('Content-Type: application/pdf');header('Content-Disposition: inline; filename="'.preg_replace('/[^A-Za-z0-9._-]/','_',$case['case_number']).'.pdf"');readfile(dirname(__DIR__).'/'.$d['storage_path']);exit; }

if ($uri==='processing') { require_auth(['processor','manager','admin']);$s=db()->query("SELECT c.id,c.case_number,c.status,c.updated_at,cu.first_name,cu.last_name,p.name partner_name,c.bike_brand,c.bike_model FROM lease_cases c JOIN customers cu ON cu.id=c.customer_id JOIN lease_partners p ON p.id=c.lease_partner_id WHERE c.status IN ('ready_for_processing','in_processing','missing_info') ORDER BY FIELD(c.priority,'urgent','high','normal'),c.signed_at ASC");render_head('Verwerking',$user);echo '<main class="shell"><h1>Verwerkingsqueue</h1><p class="muted">Oudste ondertekende dossiers eerst.</p><div class="card">';case_table($s->fetchAll(),true);echo '</div></main>';render_foot();exit; }

if (preg_match('#^processing/(\d+)/(start|complete|return)$#',$uri,$m)&&$method==='POST') { require_auth(['processor','manager','admin']);verify_csrf();$case=get_case((int)$m[1]);$action=$m[2];if($action==='start'){db()->prepare('UPDATE lease_cases SET processor_id=?,processing_started_at=NOW() WHERE id=?')->execute([$user['id'],$case['id']]);change_status((int)$case['id'],'in_processing','Verwerking gestart',(int)$user['id']);}elseif($action==='complete'){db()->prepare('UPDATE lease_cases SET processor_id=?,processed_at=NOW() WHERE id=?')->execute([$user['id'],$case['id']]);change_status((int)$case['id'],'processed','Dossier verwerkt',(int)$user['id']);audit((int)$case['id'],'CASE_PROCESSED');}else{$reason=trim((string)($_POST['reason']??'Aanvulling gevraagd'));change_status((int)$case['id'],'missing_info',$reason,(int)$user['id']);}redirect('cases/'.$case['id']); }

if (preg_match('#^processing/(\d+)$#',$uri,$m)) { require_auth(['processor','manager','admin']);redirect('cases/'.$m[1]); }

http_response_code(404);render_head('Niet gevonden',$user);echo '<main class="shell"><div class="card"><h1>Pagina niet gevonden</h1></div></main>';render_foot();

function field(string $label,string $name,string $value='',bool|string $required=false,string $type='text',string $step=''): string { return '<div class="field"><label>'.e($label).'</label><input type="'.e($type).'" name="'.e($name).'" value="'.e($value).'" '.($required===true?'required':'').($step?' step="'.e($step).'"':'').'></div>'; }
function case_table(array $cases,bool $processing=false): void { if(!$cases){echo '<div class="empty">Geen dossiers gevonden.</div>';return;}echo '<table class="table"><thead><tr><th>Dossier</th><th>Klant</th><th>Partner</th><th>Fiets</th><th>Status</th><th>Bijgewerkt</th></tr></thead><tbody>';foreach($cases as $c)echo '<tr><td><a href="'.e(base_url('cases/'.$c['id'])).'"><b>'.e($c['case_number']).'</b></a></td><td>'.e($c['first_name'].' '.$c['last_name']).'</td><td>'.e($c['partner_name']).'</td><td>'.e($c['bike_brand'].' '.$c['bike_model']).'</td><td><span class="badge '.e($c['status']).'">'.e(status_label($c['status'])).'</span></td><td>'.e($c['updated_at']).'</td></tr>';echo '</tbody></table>'; }
